import { ChatBot as cb } from './chat.pb.js';
import { base58_to_binary } from 'base58-js';

export default class ChatBot {
  constructor(token) {
    this.Token = token;
    this.uuid_ = null;
    this.Provider = 'chatgpt';
    this.System = '';
    this.ApiKey = '';
    this.Model = '';
  }

  /**
   * Ask a question of the Chat Bot. Successive calls will remember information from earlier in the conversation.
   * Use the “ResetConversation” function to reset for a new conversation.
   *
   * @param {string} question The question to send to the Chat Bot
   * @return {Promise<string>} The answer from the Chat Bot
   */
  async Converse(question) {
    const result = await this.performRequest_(this.uuid_, question, null, false);
    return result.responseText;
  }

  /**
   * Converse with the ChatBot providing an image as additional context.
   *
   * @param {string} question The question to ask the Chat Bot
   * @param {HTMLImageElement|HTMLCanvasElement|Blob} source The image to provide as context
   * @return {Promise<unknown>} The answer from the Chat Bot
   * @constructor
   */
  async ConverseWithImage(question, source) {
    if (source instanceof HTMLImageElement) {
      // Convert the image to a Uint8Array
      let canvas = document.createElement('canvas');
      canvas.width = source.width;
      canvas.height = source.height;
      let ctx = canvas.getContext('2d');
      ctx.drawImage(source, 0, 0);
      return new Promise((resolve, reject) => {
        canvas.toBlob(async (blob) => {
          if (!blob) {
            reject(new Error('Failed to convert canvas to blob'));
            return;
          }
          const array = await blob.arrayBuffer();
          const uint8Array = new Uint8Array(array);
          const response = await this.performRequest_(this.uuid_, question, uint8Array, false);
          resolve(response.responseText);
        });
      });
    } else if (source instanceof HTMLCanvasElement) {
      // Convert the canvas to a Uint8Array
      return new Promise((resolve, reject) => {
        source.toBlob(async (blob) => {
          if (!blob) {
            reject(new Error('Failed to convert canvas to blob'));
            return;
          }
          const array = await blob.arrayBuffer();
          const uint8Array = new Uint8Array(array);
          const response = await this.performRequest_(this.uuid_, question, uint8Array, false)
          resolve(response.responseText);
        });
      });
    } else if (source instanceof Blob) {
      const array = await source.arrayBuffer();
      const uint8Array = new Uint8Array(array);
      const response = this.performRequest_(this.uuid_, question, uint8Array, false);
      return response.responseText;
    } else {
      throw new Error('Source must be an HTMLImageElement or HTMLCanvasElement');
    }
  }

  /**
   * Create an image from a text description.
   *
   * @param {string} description The text description of the image to create
   * @return {Promise<{responseText: string, responseImage?: string}>} The response from the Chat Bot,
   *     including the image as a data URL and text response.
   * @constructor
   */
  CreateImage(description) {
    return this.performRequest_(this.uuid_, description, null, true);
  }

  /**
   * Reset the current conversation, Chat bot will forget
   * any previous conversation when responding in the future.
   */
  ResetConversation() {
    this.uuid_ = null;
  }

  async GotResponse(responseText) {
    return responseText;
  }

  async GotResponseWithImage(responseText, responseImage) {
    return {
      responseText: responseText,
      responseImage: responseImage
    };
  }

  /**
   * Perform the request using the ChatBot proxy.
   *
   * @param {string|null} uuid The conversation UUID, if any
   * @param {string} question The question to ask
   * @param {HTMLImageElement|Uint8Array|null} image The image to provide as context, if any
   * @param {boolean} doImage Whether to request an image response
   * @return {Promise<{responseText: string, responseImage?: string}>} The response from the Chat Bot
   * @private
   */
  async performRequest_(uuid, question, image, doImage) {
    let imgData;
    if (image instanceof HTMLImageElement) {
      let canvas = document.createElement('canvas');
      canvas.width = image.width;
      canvas.height = image.height;
      let ctx = canvas.getContext('2d');
      ctx.drawImage(image, 0, 0);
      imgData = new Uint8Array(ctx.getImageData(0, 0, image.width, image.height).data.buffer);
    } else if (image instanceof Uint8Array) {
      imgData = image;
    }
    let token = this.Token;
    if (this.Token.indexOf('%') === 0) {
      token = token.substring(1);
    }
    const binaryToken = base58_to_binary(token);
    const tokenMsg = cb.token.decode(binaryToken);
    const reqBody = {
      'token': tokenMsg,
      'uuid': this.uuid_,
      'provider': this.Provider,
      'question': question
    };
    if (this.System && !this.uuid_) {
      reqBody['system'] = this.System;
    }
    if (this.ApiKey) {
      reqBody['apikey'] = this.ApiKey;
    }
    if (this.Model) {
      reqBody['model'] = this.Model;
    }
    if (imgData) {
      reqBody['inputimage'] = imgData;
    }
    if (doImage) {
      reqBody['doimage'] = true;
    }
    const reqData = cb.request.encode(reqBody).finish();
    const responseBody = await fetch('https://chatbot.appinventor.mit.edu/chat/v1', {
      method: 'POST',
      body: reqData,
    });
    const response = await responseBody.arrayBuffer();
    const res = cb.response.decode(new Uint8Array(response));
    this.uuid_ = res.uuid;
    if (doImage) {
      return {
        'responseImage': URL.createObjectURL(new Blob([res.outputimage], { type: 'image/png' })),
        'responseText': res.answer
      };
    }
    return {'responseText': res.answer};
  }
}
